local BrickMaker = {}
local PRODUCTS = {
    sun_dried_brick = { name = "Sončno sušena opeka", clayCost = 3, sandCost = 1, time = 2, cost = 14, durability = 30, description = "Sončno sušena opeka iz gline." },
    fired_brick = { name = "Žgana opeka", clayCost = 3, sandCost = 1, fuelCost = 2, time = 4, cost = 38, durability = 55, prestige = 1, description = "Žgana opeka v peči." },
    glazed_brick = { name = "Glazirana opeka", clayCost = 4, sandCost = 1, glassCost = 1, fuelCost = 2, time = 6, cost = 90, durability = 70, prestige = 3, happiness = 1, description = "Glazirana opeka z barvno prevleko." },
    terracotta = { name = "Terrakota", clayCost = 4, sandCost = 1, fuelCost = 2, time = 7, cost = 200, durability = 80, prestige = 6, happiness = 2, description = "Terrakota za fine stavbe." },
    silver_mortar_brick = { name = "Srebrno maltinska opeka", clayCost = 5, silverCost = 1, sandCost = 1, fuelCost = 2, time = 10, cost = 440, durability = 90, prestige = 12, happiness = 3, description = "Opeka s srebrno malto za plemiče." },
    royal_grand_brick = { name = "Kraljevski veliki opeka", clayCost = 8, goldCost = 1, silverCost = 1, jewelCost = 1, sandCost = 2, fuelCost = 3, time = 15, cost = 1500, durability = 100, prestige = 35, happiness = 8, description = "Velika kraljevska opeka z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Opekarska delavnica", cost = { gold = 260, wood = 130, stone = 250 }, upkeep = 6, qualityBonus = 5 },
    kiln = { name = "Opekarska peč", cost = { gold = 900, wood = 280, stone = 500, clay = 10 }, upkeep = 22, qualityBonus = 18 },
    glazing_house = { name = "Glazirnica", cost = { gold = 2200, wood = 350, stone = 700, silver = 30, glass = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_brick_atelier = { name = "Kraljevski atelje opek", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
BrickMaker.clayStock = 24; BrickMaker.sandStock = 18; BrickMaker.fuelStock = 16; BrickMaker.glassStock = 10; BrickMaker.silverStock = 8; BrickMaker.goldStock = 6; BrickMaker.jewelStock = 6
BrickMaker.productStock = {}; BrickMaker.buildings = {}; BrickMaker.maker = nil; BrickMaker.activeMaking = {}; BrickMaker.totalProducts = 0; BrickMaker.dayTimer = 0
function BrickMaker.init() BrickMaker.clayStock=24; BrickMaker.sandStock=18; BrickMaker.fuelStock=16; BrickMaker.glassStock=10; BrickMaker.silverStock=8; BrickMaker.goldStock=6; BrickMaker.jewelStock=6; BrickMaker.productStock={}; BrickMaker.buildings={}; BrickMaker.maker=nil; BrickMaker.activeMaking={}; BrickMaker.totalProducts=0; BrickMaker.dayTimer=0; print("[BrickMaker] Royal Brick Maker System initialized (6 products, 4 buildings)") end
function BrickMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BrickMaker.maker={name=n or ("Opekar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opekar najet: %s (spretnost: %d)",BrickMaker.maker.name,s),"success") end; return true end
function BrickMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BrickMaker.build(id) local ok,e=BrickMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BrickMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BrickMaker.getQualityBonus() local b=0; for _,bd in ipairs(BrickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BrickMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and BrickMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.sandCost and BrickMaker.sandStock<(d.sandCost or 0) then return false,"Premalo peska" end; if d.fuelCost and BrickMaker.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.glassCost and BrickMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and BrickMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BrickMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BrickMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #BrickMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BrickMaker.maker then return false,"Potreben opekar" end; return true end
function BrickMaker.make(pt,qty) qty=qty or 10; local ok,e=BrickMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then BrickMaker.clayStock=BrickMaker.clayStock-d.clayCost*qty end; if d.sandCost then BrickMaker.sandStock=BrickMaker.sandStock-d.sandCost*qty end; if d.fuelCost then BrickMaker.fuelStock=BrickMaker.fuelStock-d.fuelCost*qty end; if d.glassCost then BrickMaker.glassStock=BrickMaker.glassStock-d.glassCost*qty end; if d.silverCost then BrickMaker.silverStock=BrickMaker.silverStock-d.silverCost*qty end; if d.goldCost then BrickMaker.goldStock=BrickMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BrickMaker.jewelStock=BrickMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if BrickMaker.maker then t=math.max(1,t-math.floor(BrickMaker.maker.skill/12)) end; table.insert(BrickMaker.activeMaking,{id="brick_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BrickMaker.completeMaking(m) local q=1.0+(BrickMaker.getQualityBonus()/100); if BrickMaker.maker then q=q+(BrickMaker.maker.skill/180) end; q=math.min(2.0,q); BrickMaker.productStock[m.productType]=(BrickMaker.productStock[m.productType] or 0)+m.quantity; BrickMaker.totalProducts=BrickMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BrickMaker.maker then BrickMaker.maker.itemsMade=BrickMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then BrickMaker.maker.skill=math.min(100,BrickMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Opeka izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"brick.completed",{productName=m.productName,durability=m.durability}) end end
function BrickMaker.update(dt) if not _G.state then return end; BrickMaker.dayTimer=BrickMaker.dayTimer+dt; if BrickMaker.dayTimer>=30 then BrickMaker.dayTimer=0; for i=#BrickMaker.activeMaking,1,-1 do local m=BrickMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BrickMaker.completeMaking(m); table.remove(BrickMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BrickMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BrickMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BrickMaker.getStats() return {clayStock=BrickMaker.clayStock,sandStock=BrickMaker.sandStock,fuelStock=BrickMaker.fuelStock,glassStock=BrickMaker.glassStock,silverStock=BrickMaker.silverStock,goldStock=BrickMaker.goldStock,jewelStock=BrickMaker.jewelStock,productStock=BrickMaker.productStock,numBuildings=#BrickMaker.buildings,hasMaker=BrickMaker.maker~=nil,makerName=BrickMaker.maker and BrickMaker.maker.name or "—",makerSkill=BrickMaker.maker and BrickMaker.maker.skill or 0,activeMaking=#BrickMaker.activeMaking,totalProducts=BrickMaker.totalProducts} end
return BrickMaker
